-- Trigger to notify on credit changes
CREATE OR REPLACE FUNCTION notify_credit_change()
RETURNS TRIGGER AS $$
BEGIN
  PERFORM pg_notify(
    'credit_updated',
    json_build_object(
      'user_id', NEW.id,
      'credits', NEW.credits
    )::text
  );
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER user_credits_notify
AFTER UPDATE OF credits ON users
FOR EACH ROW
EXECUTE FUNCTION notify_credit_change();
