            Sign up
          </Link>
        </p>
      </div>
    </div>
  );
}
```

### Signup Form

```typescript
// app/signup/page.tsx
'use client';

import { useRouter } from 'next/navigation';
import bcrypt from 'bcryptjs';

export default function SignupPage() {
  const router = useRouter();

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);

    const response = await fetch('/api/auth/signup', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        email: formData.get('email'),
        password: formData.get('password'),
        name: formData.get('name'),
      }),
    });

    if (response.ok) {
      // Sign in after signup
      await signIn('credentials', {
        email: formData.get('email') as string,
        password: formData.get('password') as string,
        callbackUrl: '/onboarding',
      });
    }
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-4">
      {/* Form fields */}
    </form>
  );
}
```

### Signup API Route

```typescript
// app/api/auth/signup/route.ts
import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import bcrypt from 'bcryptjs';
import { z } from 'zod';

const SignupSchema = z.object({
  email: z.string().email(),
  password: z.string().min(8),
  name: z.string().min(1),
});

export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const { email, password, name } = SignupSchema.parse(body);

    // Check if user exists
    const existingUser = await prisma.user.findUnique({
      where: { email }
    });

    if (existingUser) {
      return NextResponse.json(
        { error: 'Email already registered' },
        { status: 400 }
      );
    }

    // Hash password
    const passwordHash = await bcrypt.hash(password, 12);

    // Create user
    const user = await prisma.user.create({
      data: {
        email,
        name,
        passwordHash,
        role: 'user',
        credits: 10, // Welcome credits
      }
    });

    return NextResponse.json(
      { message: 'User created', userId: user.id },
      { status: 201 }
    );
  } catch (error) {
    if (error instanceof z.ZodError) {
      return NextResponse.json(
        { error: 'Invalid input', details: error.errors },
        { status: 400 }
      );
    }

    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}
```

---

## Protected Routes (Middleware)

```typescript
// middleware.ts
import { withAuth } from 'next-auth/middleware';
import { NextResponse } from 'next/server';

export default withAuth(
  function middleware(req) {
    const token = req.nextauth.token;
    const isAdminRoute = req.nextUrl.pathname.startsWith('/admin');

    // Admin route protection
    if (isAdminRoute && token?.role !== 'admin') {
      return NextResponse.redirect(new URL('/dashboard', req.url));
    }

    return NextResponse.next();
  },
  {
    callbacks: {
      authorized: ({ token }) => !!token,
    },
  }
);

export const config = {
  matcher: [
    '/dashboard/:path*',
    '/builder/:path*',
    '/admin/:path*',
    '/profile/:path*',
  ]
};
```

---

## Session Management

### Client-Side Session

```typescript
'use client';

import { useSession } from 'next-auth/react';

export function UserProfile() {
  const { data: session, status } = useSession();

  if (status === 'loading') return <Skeleton />;
  if (status === 'unauthenticated') return <LoginButton />;

  return (
    <div>
      <p>Welcome, {session.user.name}</p>
      <p>Credits: {session.user.credits}</p>
    </div>
  );
}
```

### Server-Side Session

```typescript
// Server Component
import { getServerSession } from 'next-auth';
import { authOptions } from '@/app/api/auth/[...nextauth]/route';

export default async function Page() {
  const session = await getServerSession(authOptions);

  if (!session) {
    redirect('/login');
  }

  return <div>Hello {session.user.name}</div>;
}
```

---

## Migration Strategy

### Phase 1: Parallel Running
1. Install NextAuth alongside Firebase Auth
2. Create new signup flow with NextAuth
3. Existing users continue with Firebase

### Phase 2: User Migration
```typescript
// Migration script
async function migrateFirebaseUsers() {
  const firebaseUsers = await admin.auth().listUsers();

  for (const fbUser of firebaseUsers.users) {
    // Create in PostgreSQL
    await prisma.user.upsert({
      where: { email: fbUser.email! },
      update: {
        emailVerified: fbUser.emailVerified,
        emailVerifiedAt: fbUser.emailVerified ? new Date() : null,
      },
      create: {
        id: fbUser.uid,
        email: fbUser.email!,
        name: fbUser.displayName || 'User',
        emailVerified: fbUser.emailVerified,
        passwordHash: null, // Users must reset password
        role: 'user',
      }
    });

    // Create OAuth accounts
    for (const provider of fbUser.providerData) {
      await prisma.account.create({
        data: {
          userId: fbUser.uid,
          type: 'oauth',
          provider: provider.providerId.replace('.com', ''),
          providerAccountId: provider.uid,
        }
      });
    }
  }
}
```

### Phase 3: Password Reset
- Force password reset for credential users
- Send email with reset link
- Users set new password in NextAuth

---

## TypeScript Types

```typescript
// types/next-auth.d.ts
import 'next-auth';

declare module 'next-auth' {
  interface User {
    id: string;
    role: string;
    credits: number;
  }

  interface Session {
    user: User & {
      id: string;
      role: string;
      credits: number;
    }
  }
}

declare module 'next-auth/jwt' {
  interface JWT {
    userId: string;
    role: string;
    credits: number;
  }
}
```

---

## Summary

NextAuth.js provides:
- ✅ Seamless Next.js integration
- ✅ Multiple auth providers
- ✅ Type-safe sessions
- ✅ Middleware protection
- ✅ Prisma adapter for PostgreSQL

Migration requires password reset for existing users but provides better long-term flexibility.
"}

{"file_path": "docs/migration/MIGRATION_PLAN.md", "initial_content": "# Phased Migration Plan - Firebase to PostgreSQL

## Executive Summary

**Objective**: Migrate Arkan from Firebase (Firestore + Auth) to PostgreSQL with NextAuth, Prisma, and Hasura while maintaining zero downtime and data integrity.

**Timeline**: 6-8 weeks  
**Risk Level**: High (financial data migration)  
**Rollback Strategy**: Parallel systems for 2 weeks

---

## Migration Phases Overview

| Phase | Duration | Focus Area | Risk | Dependencies |
|-------|----------|------------|------|--------------|
| **Phase 0** | 1 week | Infrastructure Setup | Low | None |
| **Phase 1** | 1 week | Schema & Database | Medium | Phase 0 |
| **Phase 2** | 2 weeks | Authentication Migration | Medium | Phase 1 |
| **Phase 3** | 2 weeks | Data Migration & Validation | **High** | Phase 2 |
| **Phase 4** | 1 week | Real-time Features | Medium | Phase 3 |
| **Phase 5** | 1 week | Testing & Optimization | Medium | Phase 4 |
| **Phase 6** | 1 week | Cutover & Monitoring | **High** | Phase 5 |

---

## Phase 0: Infrastructure Setup (Week 1)

### Goals
- Setup local PostgreSQL development environment
- Configure Prisma
- Setup Hasura
- Prepare Docker environment

### Tasks

#### 1. Docker Configuration
```yaml
# docker-compose.yml additions
services:
  postgres:
    image: postgres:15-alpine
    container_name: arkan-postgres
    environment:
      POSTGRES_DB: arkan_dev
      POSTGRES_USER: arkan_user
      POSTGRES_PASSWORD: ${DB_PASSWORD}
    ports:
      - "5432:5432"
    volumes:
      - postgres_data:/var/lib/postgresql/data
    healthcheck:
      test: ["CMD-SHELL", "pg_isready -U arkan_user"]
      interval: 10s
      timeout: 5s
      retries: 5

  hasura:
    image: hasura/graphql-engine:v2.36.0
    container_name: arkan-hasura
    depends_on:
      postgres:
        condition: service_healthy
    ports:
      - "8080:8080"
    environment:
      HASURA_GRAPHQL_DATABASE_URL: postgresql://arkan_user:${DB_PASSWORD}@postgres:5432/arkan_dev
      HASURA_GRAPHQL_ENABLE_CONSOLE: "true"
      HASURA_GRAPHQL_DEV_MODE: "true"
      HASURA_GRAPHQL_ADMIN_SECRET: ${HASURA_ADMIN_SECRET}
      HASURA_GRAPHQL_JWT_SECRET: '{"type":"HS256","key":"${NEXTAUTH_SECRET}"}'

volumes:
  postgres_data:
```

#### 2. Prisma Setup
```bash
# Install dependencies
npm install prisma @prisma/client
npm install -D prisma

# Initialize Prisma
npx prisma init

# Copy schema from docs/migration/schema.prisma
# Generate client
npx prisma generate

# Create initial migration
npx prisma migrate dev --name init
```

#### 3. Environment Configuration
```env
# .env.local
DATABASE_URL="postgresql://arkan_user:password@localhost:5432/arkan_dev"
DIRECT_URL="postgresql://arkan_user:password@localhost:5432/arkan_dev"

NEXTAUTH_URL="http://localhost:9002"
NEXTAUTH_SECRET="your-32-char-secret-key-here"

HASURA_ADMIN_SECRET="hasura-admin-secret"
HASURA_GRAPHQL_URL="http://localhost:8080/v1/graphql"
